	cps wa, 0
	jr lt, IsColorValid_Check256
	cp wa, 0xFF
	jr le, IsColorValid_Valid

IsColorValid_Check256:
	cp wa, 0x100
	jr lt, IsColorValid_Invalid
	cp wa, 0x100
	jr gt, IsColorValid_Invalid

IsColorValid_Valid:
	lds hl, 1
	ret

IsColorValid_Invalid:
	lds hl, 0
	ret

ClampColorToRange:
	ld hl, bc
	cps bc, 0
	ret lt
	cp bc, 0xFF
	ret gt
	ret

